// Tabs + search over a verified catalog generated by the Java engine.
// This file intentionally contains no pluralization rules: the browser never invents a form.
const SN = {
  "Maven": '<dependency>\n  <groupId>io.github.slayyyyer.morphex</groupId>\n  <artifactId>english-inflector-core</artifactId>\n  <version>1.2.0</version>\n</dependency>',
  "Gradle (Kotlin)": 'implementation("io.github.slayyyyer.morphex:english-inflector-core:1.2.0")',
  "Gradle (Groovy)": "implementation 'io.github.slayyyyer.morphex:english-inflector-core:1.2.0'",
  "From source": './mvnw install   # JDK 17+; wrapper pins Maven 3.9.9'
};
const tabs = document.getElementById('tabs');
const snip = document.getElementById('snip');
function pick(k) {
  if (!snip || !tabs) return;
  snip.textContent = SN[k];
  [...tabs.children].forEach(b => b.setAttribute('aria-selected', b.textContent === k));
}
if (tabs) {
  Object.keys(SN).forEach(k => {
    const b = document.createElement('button');
    b.className = 'tab';
    b.setAttribute('role', 'tab');
    b.textContent = k;
    b.onclick = () => pick(k);
    tabs.appendChild(b);
  });
  pick("Maven");
}

const demoInput = document.getElementById('w');
const out = document.getElementById('o');
const why = document.getElementById('y');
const detail = document.getElementById('detail');
const list = document.getElementById('list');
const chips = document.getElementById('chips');
const catalogNote = document.getElementById('catalog-note');
let catalog = [];
let selectedId = null;

function setCatalogNote(message) {
  if (catalogNote) catalogNote.textContent = message;
}

function configLabel(entry) {
  const parts = [];
  if (entry.casePolicy && entry.casePolicy !== 'PRESERVE') parts.push(entry.casePolicy.toLowerCase());
  if (entry.mode && entry.mode !== 'ANGLICIZED') parts.push(entry.mode.toLowerCase());
  if (entry.uppercasePolicy && entry.uppercasePolicy !== 'INFER_INITIALISM') {
    parts.push(entry.uppercasePolicy.toLowerCase());
  }
  const overrides = Object.entries(entry.overrides || {});
  if (overrides.length) parts.push('override ' + overrides.map(([k, v]) => `${k}→${v}`).join(', '));
  if ((entry.initialisms || []).length) parts.push('initialism ' + entry.initialisms.join(', '));
  return parts.join(' · ');
}

function selectEntry(entry) {
  if (!entry) return;
  selectedId = entry.id;
  if (out) out.textContent = entry.plural;
  if (why) {
    why.textContent = `${entry.input} → ${entry.plural} · ${entry.source} (${entry.sourceId}) · ${entry.countability}`;
  }
  if (detail) {
    const parts = [];
    const config = configLabel(entry);
    if (config) parts.push(config);
    if (entry.invariant) parts.push('invariant');
    if (entry.ambiguous) parts.push('ambiguous');
    if ((entry.alternatives || []).length) parts.push('alternatives: ' + entry.alternatives.join(', '));
    if (entry.note) parts.push(entry.note);
    detail.textContent = parts.join(' · ');
  }
  if (list) {
    [...list.querySelectorAll('button')].forEach(button => {
      button.setAttribute('aria-pressed', String(button.dataset.id === selectedId));
    });
  }
}

function matches(entry, query) {
  if (!query) return true;
  const haystack = [
    entry.input, entry.plural, entry.group, entry.note,
    entry.sourceId, entry.casePolicy, entry.mode
  ].join(' ').toLowerCase();
  return haystack.includes(query.toLowerCase());
}

function renderResults(query) {
  if (!list || !catalog.length) return;
  const found = catalog.filter(entry => matches(entry, query));
  list.replaceChildren();
  if (!found.length) {
    const empty = document.createElement('div');
    empty.className = 'catalog-empty';
    empty.textContent = 'No verified example matches. The catalog is fixed; arbitrary input is not evaluated in the browser.';
    list.appendChild(empty);
    if (out) out.textContent = '—';
    if (why) why.textContent = 'No catalog row selected.';
    if (detail) detail.textContent = '';
    selectedId = null;
    return;
  }
  found.slice(0, 8).forEach(entry => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'case-btn';
    button.dataset.id = entry.id;
    button.setAttribute('aria-pressed', String(entry.id === selectedId));
    button.textContent = `${entry.input} → ${entry.plural}`;
    button.title = `${entry.group} · ${entry.source}`;
    button.onclick = () => selectEntry(entry);
    list.appendChild(button);
  });
  if (!found.some(entry => entry.id === selectedId)) selectEntry(found[0]);
}

async function initCatalog() {
  if (!demoInput) return;
  try {
    const response = await fetch('./catalog.json', { cache: 'no-store' });
    if (!response.ok) throw new Error('HTTP ' + response.status);
    const data = await response.json();
    if (!Array.isArray(data.cases) || !data.cases.length) throw new Error('empty catalog');
    catalog = data.cases;
    setCatalogNote(`${data.count} verified cases generated by ${data.engine}. Search filters these rows; arbitrary input is not evaluated in the browser.`);
    if (chips) {
      chips.replaceChildren();
      catalog.filter(entry => entry.featured).forEach(entry => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'chip';
        button.textContent = entry.input;
        button.onclick = () => {
          demoInput.value = entry.input;
          selectEntry(entry);
          renderResults(entry.input);
        };
        chips.appendChild(button);
      });
    }
    const initial = catalog.find(entry => entry.id === 'compound-mother-in-law') || catalog[0];
    demoInput.value = initial.input;
    selectEntry(initial);
    renderResults(initial.input);
  } catch (error) {
    setCatalogNote(`Verified catalog unavailable (${error.message}). No substitute form is shown; the browser does not approximate the Java engine.`);
    if (out) out.textContent = '—';
    if (why) why.textContent = '';
    if (detail) detail.textContent = '';
  }
}

if (demoInput) {
  demoInput.addEventListener('input', () => renderResults(demoInput.value.trim()));
  initCatalog();
}
